True def transform(grid):
    out=[row[:] for row in grid]
    pat=[[4,5,5],[8,5,8],[8,5,0]]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    for r,c in pts:
        for dr in range(3):
            for dc in range(3):
                v=pat[dr][dc]
                if v!=4 and 0<=r+dr-2<len(grid) and 0<=c+dc-2<len(grid[0]): out[r+dr-2][c+dc-2]=v
    return out
